// C++11: Provides the strongest optimization guarantees.
// The compiler isn't required to keep the stack unwindable.
int f_modern(int x) noexcept;

// C++98 Style: Weaker guarantees than noexcept.
// The stack MUST be unwound before std::terminate is called.
int f_legacy(int x) throw();

// No Specification: Assumed to potentially throw.
// The compiler must generate code for full exception handling.
int f_default(int x);

class Widget {
public:
    // Marking move operations noexcept is critical for container performance.
    Widget(Widget&& other) noexcept { /* ... */ }
    Widget& operator=(Widget&& other) noexcept { /* ... */ }
};
